class FactorialClient:
    """
    High-level Factorial API client.

    Usage:
        client = FactorialClient(api_key="YOUR_KEY")
        employees = client.employees.employees.list()
        for emp in client.employees.employees.paginate(max_items=50):
            print(emp)
    """

    def __init__(
        self,
        *,
        api_key: str | None = None,
        token: str | None = None,
        base_url: str | None = None,
    ) -> None:
        api_key = api_key or os.environ.get("FACTORIAL_API_KEY")
        token = token or os.environ.get("FACTORIAL_TOKEN")
        base_url = base_url or os.environ.get("FACTORIAL_BASE_URL") or "https://api.factorialhr.com"
        auth_token = api_key or token
        if not auth_token:
            raise ValueError(
                "Provide api_key or token (or set FACTORIAL_API_KEY / FACTORIAL_TOKEN)"
            )
        self._client = AuthenticatedClient(
            base_url=base_url,
            token=auth_token,
            prefix="",
            auth_header_name="x-api-key",
            raise_on_unexpected_status=True,
        )
        self.api_public = ApiPublicNamespace(self._client)
        self.approvals = ApprovalsNamespace(self._client)
        self.ats = AtsNamespace(self._client)
        self.attendance = AttendanceNamespace(self._client)
        self.banking = BankingNamespace(self._client)
        self.bookkeepers_management = BookkeepersManagementNamespace(self._client)
        self.companies = CompaniesNamespace(self._client)
        self.compensations = CompensationsNamespace(self._client)
